import java.util.*;

class Solution {
    public boolean isSorted(int[] nums) {
        int[] copy = Arrays.copyOf(nums, nums.length);
        Arrays.sort(copy);

        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != copy[i]) {
                return false;
            }
        }

        return true;
    }
}
